const test = require('node:test');
const assert = require('node:assert/strict');
const { bookingLine } = require('../studio/service.cjs');
const { permitted } = require('../studio/access.cjs');
test('room permission uses array values, never array properties', () => {
  assert.equal(bookingLine('mix'),'mix: allowed');
  assert.equal(bookingLine('voice'),'voice: allowed');
  for (const room of ['0','1','length','map','Mix','','mix-extra']) {
    assert.equal(bookingLine(room),room + ': denied');
  }
  const config = Object.freeze({allowedRooms:Object.freeze(['0','length'])});
  assert.equal(permitted('0',config),true);
  assert.equal(permitted('length',config),true);
  assert.equal(permitted('mix',config),false);
  assert.equal(permitted('mix',{allowedRooms:[]}),false);
});

